import base64, gzip, hashlib, re, sys
from pathlib import Path

MAIN_IN = 'e26b2943105e507ff9165fc87c1afe51905d6bd87e9a6af994c8cd16498afa10'
MAIN_OUT = '22af420f4b9959a140db24a4fff59709eaae2979ecdfc53df7afbac147526f0b'
DESKTOP_IN = '2d92d059b297d146e2c6a893a0c81fef3a7ca2e0b2e1abd887f79c25640e6ab5'
DESKTOP_OUT = '88936b09a93d67fd070623b7e95306377fee11e0407883cb9910f63f12ac1752'

MAIN_PATCH_GZ_B64 = ''
DESKTOP_PATCH_GZ_B64 = ''


def apply_patch(target: Path, patch_text: str, expected_in: str, expected_out: str, label: str):
    raw = target.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected_in:
        raise SystemExit(f'{label} input mismatch: {digest}')
    src = raw.decode('utf-8').splitlines(keepends=True)
    pl = patch_text.splitlines(keepends=True)
    hunk_re = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')
    i = 0
    while i < len(pl) and not pl[i].startswith('@@ '): i += 1
    out=[]; src_pos=0; hunk_no=0
    while i < len(pl):
        m=hunk_re.match(pl[i])
        if not m: raise SystemExit(f'{label} bad hunk header: {pl[i]!r}')
        old_start=int(m.group(1)); old_count=int(m.group(2) or '1'); new_count=int(m.group(4) or '1')
        expected_pos=old_start-1
        if expected_pos < src_pos: raise SystemExit(f'{label} overlapping hunks')
        out.extend(src[src_pos:expected_pos]); src_pos=expected_pos
        i += 1; seen_old=0; seen_new=0; hunk_no += 1
        while i < len(pl) and not pl[i].startswith('@@ '):
            line=pl[i]
            if line.startswith('\\ No newline at end of file'): i += 1; continue
            kind=line[0]; body=line[1:]
            if kind in (' ', '-'):
                if src_pos >= len(src) or src[src_pos] != body:
                    got='<EOF>' if src_pos >= len(src) else src[src_pos]
                    raise SystemExit(f'{label} hunk {hunk_no} mismatch at {src_pos+1}: expected {body!r}, got {got!r}')
                seen_old += 1
                if kind == ' ': out.append(src[src_pos]); seen_new += 1
                src_pos += 1
            elif kind == '+': out.append(body); seen_new += 1
            else: raise SystemExit(f'{label} unsupported patch record: {line!r}')
            i += 1
        if seen_old != old_count or seen_new != new_count:
            raise SystemExit(f'{label} hunk {hunk_no} count mismatch')
    out.extend(src[src_pos:])
    encoded=''.join(out).encode('utf-8')
    out_digest=hashlib.sha256(encoded).hexdigest()
    if out_digest != expected_out: raise SystemExit(f'{label} output mismatch: {out_digest}')
    target.write_bytes(encoded)
    print(f'{label}_OK {out_digest}')

if len(sys.argv) != 3:
    raise SystemExit('usage: apply_v01103_delta.py MAIN_PY DESKTOP_ACTIONS_PY')
main=Path(sys.argv[1]).resolve(); desktop=Path(sys.argv[2]).resolve()
apply_patch(main, gzip.decompress(base64.b64decode(MAIN_PATCH_GZ_B64)).decode('utf-8'), MAIN_IN, MAIN_OUT, 'V01103_MAIN')
apply_patch(desktop, gzip.decompress(base64.b64decode(DESKTOP_PATCH_GZ_B64)).decode('utf-8'), DESKTOP_IN, DESKTOP_OUT, 'V01103_DESKTOP')
